-- Layout Assistant 0.1.0 / grandMA2 3.9 / Lua 5.3
-- Generated by tools/build.py. Edit src/, then rebuild.
local factories, loaded = {}, {}
local function require(name)
    if loaded[name] then return loaded[name] end
    assert(factories[name], "Unknown bundled module: " .. name)
    local result = factories[name]()
    loaded[name] = result
    return result
end
factories["layout_assistant.xml"] = function()
-- A deliberately restricted, span-preserving reader for grandMA2 exports.
-- No entity expansion, DTD, schema fetching, or execution of input data.
local M = {}
local function check(v, message) if not v then error(message, 0) end return v end

function M.parse(text)
    check(type(text) == 'string' and #text <= 16 * 1024 * 1024, 'XML: invalid size (max 16 MiB)')
    local doc = {name = '#document', children = {}, text = text}
    local stack, pos, count = {doc}, 1, 0
    while true do
        local s = text:find('<', pos, true)
        local between = text:sub(pos, s and s - 1 or #text)
        if #stack == 1 then
            if pos == 1 then between = between:gsub('^\239\187\191', '') end
            check(between:match('^%s*$'), 'XML: text outside root')
        end
        if not s then break end
        if text:sub(s, s + 3) == '<!--' then
            local e = check(text:find('-->', s + 4, true), 'XML: unclosed comment')
            pos = e + 3
        elseif text:sub(s, s + 1) == '<?' then
            local e = check(text:find('?>', s + 2, true), 'XML: unclosed processing instruction')
            pos = e + 2
        else
            check(text:sub(s, s + 1) ~= '<!', 'XML: DTD/CDATA/declarations unsupported')
            local i, quote = s + 1, nil
            while i <= #text do
                local c = text:sub(i, i)
                if quote then if c == quote then quote = nil end
                elseif c == '"' or c == "'" then quote = c
                elseif c == '>' then break end
                i = i + 1
            end
            check(i <= #text, 'XML: unclosed tag')
            local raw = text:sub(s, i)
            local closing = raw:match('^</([%w_:.-]+)%s*>$')
            if closing then
                check(#stack > 1 and stack[#stack].name == closing, 'XML: mismatched closing tag')
                stack[#stack].finish = i
                table.remove(stack)
            else
                local name, after = raw:match('^<([%w_:.-]+)()')
                check(name, 'XML: invalid tag')
                local node = {name = name, start = s, open_end = i, attrs = {}, children = {}}
                local tail = raw:match('/%s*>$') and '/%s*>$' or '>%s*$'
                local cursor = after
                while true do
                    local rest = raw:sub(cursor)
                    if rest:match('^%s*' .. tail) then break end
                    local a, b, key, q, value, vs, ve
                    a, b, key, q = rest:find('^%s+([%w_:.-]+)%s*=%s*([\'\"])')
                    check(a, 'XML: malformed attributes')
                    vs = cursor + b
                    ve = check(raw:find(q, vs, true), 'XML: unclosed attribute') - 1
                    value = raw:sub(vs, ve)
                    check(not node.attrs[key] and not value:find('<', 1, true), 'XML: duplicate/invalid attribute')
                    node.attrs[key] = {value = value, first = s + vs - 1, last = s + ve - 1}
                    cursor = ve + 2
                end
                local parent = stack[#stack]
                node.parent = parent
                parent.children[#parent.children + 1] = node
                count = count + 1
                check(count <= 200000 and #stack < 64, 'XML: complexity limit')
                if raw:match('/%s*>$') then node.finish = i else stack[#stack + 1] = node end
            end
            pos = i + 1
        end
    end
    check(#stack == 1 and #doc.children == 1, 'XML: expected one complete root')
    return doc
end

function M.value(node, key)
    return node.attrs[key] and node.attrs[key].value
end

function M.children(node, name)
    local out = {}
    for _, child in ipairs(node.children) do
        if child.name == name then out[#out + 1] = child end
    end
    return out
end

function M.one(node, name)
    local found = M.children(node, name)
    check(#found == 1, 'XML: expected one ' .. name)
    return found[1]
end

function M.patch(text, edits)
    table.sort(edits, function(a, b) return a.first < b.first end)
    local out, cursor = {}, 1
    for _, edit in ipairs(edits) do
        check(edit.first >= cursor and edit.last >= edit.first, 'XML: overlapping edits')
        out[#out + 1] = text:sub(cursor, edit.first - 1)
        out[#out + 1] = edit.value
        cursor = edit.last + 1
    end
    out[#out + 1] = text:sub(cursor)
    return table.concat(out)
end
return M

end
factories["layout_assistant.core"] = function()
local xml = require('layout_assistant.xml')
local M = {}
local function check(v, message) if not v then error(message, 0) end return v end
function M.number(v, what)
    local n = tonumber(v)
    check(n and n == n and math.abs(n) <= 1000000, 'Invalid finite number: ' .. (what or '?'))
    return n
end
function M.id(v)
    local n = M.number(v, 'ID')
    check(n > 0 and n % 1 == 0, 'Expected positive integer ID')
    return math.floor(n)
end
function M.index(v)
    if v == 'root' then return v end
    local n = M.number(v, 'raw sub_index')
    check(n >= 0 and n % 1 == 0, 'Expected raw integer sub_index or root')
    return string.format('%.0f', n)
end
function M.rotate(x, y, degrees)
    local r = M.number(degrees, 'angle') * math.pi / 180
    return x * math.cos(r) - y * math.sin(r), x * math.sin(r) + y * math.cos(r)
end
function M.transform(x, y, source, target)
    local u, v = M.rotate(x - source.x, y - source.y, -source.angle)
    local mirror = target.mirror or 'none'
    check(mirror == 'none' or mirror == 'flip_x' or mirror == 'flip_y', 'Unknown mirror mode')
    if mirror == 'flip_x' then u = -u elseif mirror == 'flip_y' then v = -v end
    u, v = M.rotate(u, v, target.angle)
    return target.x + u, target.y + v
end

function M.read(text)
    local doc = xml.parse(text)
    local root = doc.children[1]
    check(root.name == 'MA' and xml.value(root, 'xmlns') == 'http://schemas.malighting.de/grandma2/xml/MA', 'Expected MA2 namespace')
    check(xml.value(root, 'major_vers') == '3' and xml.value(root, 'minor_vers') == '9', 'Only MA2 3.9 exports supported')
    -- Reject multi-object exports: importing them could affect unrelated pools.
    for _, child in ipairs(root.children) do
        check(child.name == 'Info' or child.name == 'Group', 'Unexpected top-level object: ' .. child.name)
    end
    local group = xml.one(root, 'Group')
    local data = xml.one(group, 'LayoutData')
    local fixtures = xml.one(data, 'SubFixtures')
    local model = {text = text, group = group, elements = {}, by_fixture = {}, ignored = 0}
    for _, node in ipairs(xml.children(fixtures, 'LayoutSubFix')) do
        local ref = xml.one(node, 'Subfixture')
        local raw_fid = xml.value(ref, 'fix_id')
        if not raw_fid or raw_fid == '0' then
            -- Channels and deleted references are not candidates; preserve their bytes.
            model.ignored = model.ignored + 1
        else
        local fid = M.id(raw_fid)
        local key = xml.value(ref, 'sub_index')
        key = key and M.index(key) or 'root'
        local elem = {fix_id = fid, index = key, node = node,
            x = M.number(xml.value(node, 'center_x'), 'center_x'),
            y = M.number(xml.value(node, 'center_y'), 'center_y')}
        model.by_fixture[fid] = model.by_fixture[fid] or {}
        check(not model.by_fixture[fid][key], 'Ambiguous duplicate Layout element: ' .. fid .. '/' .. key)
        model.by_fixture[fid][key] = elem
        model.elements[#model.elements + 1] = elem
        end
    end
    check(#model.elements > 0, 'No fixture elements in Layout')
    return model
end

function M.indices(model, fid)
    local elements = check(model.by_fixture[M.id(fid)], 'Fixture missing from Layout')
    local keys = {}
    for key in pairs(elements) do keys[#keys + 1] = key end
    table.sort(keys, function(a, b)
        if a == 'root' then return b ~= 'root' end
        if b == 'root' then return false end
        return tonumber(a) < tonumber(b)
    end)
    return keys
end

local function select_elements(model, fid, indices)
    local elements = check(model.by_fixture[M.id(fid)], 'Fixture missing from Layout: ' .. tostring(fid))
    check(type(indices) == 'table' and #indices > 0, 'Explicit nonempty index list required')
    local selected, seen = {}, {}
    for _, index in ipairs(indices) do
        local key = M.index(index)
        check(not seen[key], 'Repeated sub_index: ' .. key)
        seen[key] = true
        selected[#selected + 1] = check(elements[key], 'Missing element: ' .. fid .. '/' .. key)
    end
    return selected
end
local function frame(elements, spec)
    check((spec.x == nil) == (spec.y == nil), 'Anchor needs both x and y')
    local x, y = 0, 0
    for _, elem in ipairs(elements) do x, y = x + elem.x, y + elem.y end
    return {x = spec.x == nil and x / #elements or M.number(spec.x, 'anchor x'),
        y = spec.y == nil and y / #elements or M.number(spec.y, 'anchor y'),
        angle = M.number(spec.angle, 'angle'), mirror = spec.mirror or 'none'}
end

-- All jobs read the same immutable snapshot. Conflicting writes are rejected.
function M.plan(model, config)
    check(type(config) == 'table' and type(config.jobs) == 'table' and #config.jobs > 0, 'Nonempty jobs required')
    local plan = {changes = {}, edits = {}, source_text = model.text}
    local used, sources = {}, {}
    for _, job in ipairs(config.jobs) do
        check(type(job.source) == 'table', 'Source required')
        sources[M.id(job.source.fix_id)] = true
    end
    for _, job in ipairs(config.jobs) do
        local source = job.source
        local selected = select_elements(model, source.fix_id, source.indices)
        local origin = frame(selected, source)
        check(type(job.targets) == 'table' and #job.targets > 0, 'Targets required')
        for _, target in ipairs(job.targets) do
            local fid = M.id(target.fix_id)
            check(not sources[fid], 'A template fixture cannot also be a target')
            local indices = target.indices or source.indices
            check(#indices == #selected, 'Source/target index count mismatch')
            local mapped = select_elements(model, fid, indices)
            local destination = frame(mapped, target)
            for i, before in ipairs(mapped) do
                local key = fid .. '/' .. before.index
                check(not used[key], 'Conflicting target: ' .. key)
                used[key] = true
                local x, y = M.transform(selected[i].x, selected[i].y, origin, destination)
                x, y = M.number(x, 'result x'), M.number(y, 'result y')
                local change = {fix_id = fid, index = before.index, source_index = selected[i].index,
                    before_x = before.x, before_y = before.y, x = x, y = y}
                plan.changes[#plan.changes + 1] = change
                for _, pair in ipairs({{'center_x', x}, {'center_y', y}}) do
                    local attr = before.node.attrs[pair[1]]
                    local value = math.abs(pair[2]) < 0.0000005 and 0 or pair[2]
                    plan.edits[#plan.edits + 1] = {first = attr.first, last = attr.last, value = string.format('%.6f', value)}
                end
            end
        end
    end
    plan.output = xml.patch(model.text, plan.edits)
    return plan
end

function M.report(plan)
    local lines = {'Layout Assistant 0.1.0 - PREVIEW',
        'Only center_x/center_y change in a NEW Layout copy. Icons/sizes/patch stay as exported.',
        'Fixture/raw_index <- source_raw_index: old x,y -> new x,y'}
    for _, c in ipairs(plan.changes) do
        lines[#lines + 1] = string.format('%d/%s <- %s: %.6f,%.6f -> %.6f,%.6f',
            c.fix_id, c.index, c.source_index, c.before_x, c.before_y, c.x, c.y)
    end
    return table.concat(lines, '\n') .. '\n'
end
return M

end
factories["layout_assistant.ma2"] = function()
local core = require('layout_assistant.core')
local M = {}
local function check(v, message) if not v then error(message, 0) end return v end
local serial = 0

function M.new(gma_api, filesystem)
    local g = check(gma_api, 'grandMA2 API missing')
    local fs = filesystem or io
    local self = {}
    local obj = check(g.show and g.show.getobj, 'gma.show.getobj missing')
    check(type(obj.handle) == 'function', 'getobj.handle missing')
    local function handle(id)
        local h = obj.handle('Layout ' .. core.id(id))
        if h == false or h == 0 then return nil end
        return h
    end
    function self.log(message) g.feedback(tostring(message)) end
    function self.ask(title, default)
        local result = g.textinput(title, default or '')
        if result == nil or result == false then error('Cancelled', 0) end
        return result
    end
    function self.exists(path)
        local f = fs.open(path, 'rb')
        if f then f:close(); return true end
        return false
    end
    function self.read(path)
        local f, err = fs.open(path, 'rb')
        check(f, 'Cannot read file: ' .. path .. ' (' .. tostring(err) .. ')')
        local data = f:read(16 * 1024 * 1024 + 1)
        f:close()
        check(data and #data <= 16 * 1024 * 1024, 'File empty or over 16 MiB')
        return data
    end
    function self.write_new(path, text)
        check(not self.exists(path), 'Refusing to overwrite file: ' .. path)
        local f, err = fs.open(path, 'wb')
        check(f, 'Cannot write file: ' .. path .. ' (' .. tostring(err) .. ')')
        local ok, write_err = f:write(text)
        local closed, close_err = f:close()
        check(ok and closed, 'File write failed: ' .. tostring(write_err or close_err))
    end
    function self.directory(path)
        check(type(path) == 'string' and #path > 0 and #path <= 512, 'Absolute existing directory required')
        path = path:gsub('\\', '/')
        check(path:match('^/') or path:match('^%a:/'), 'Directory must be absolute')
        check(not path:find('[%c";`$<>|]'), 'Unsafe character in directory')
        local cleaned = path:gsub('/+$', '')
        check(cleaned ~= '' and not cleaned:match('^%a:$'), 'Use an existing subdirectory, not a drive root')
        return cleaned
    end
    function self.basename(dir, role)
        for _ = 1, 1000 do
            serial = serial + 1
            local name = 'la_' .. role .. '_' .. os.date('%Y%m%d_%H%M%S') .. '_' .. serial
            if not self.exists(dir .. '/' .. name .. '.xml') and not self.exists(dir .. '/' .. name .. '.txt') then return name end
        end
        error('Cannot allocate a new filename', 0)
    end
    function self.export(layout, dir)
        layout, dir = core.id(layout), self.directory(dir)
        check(handle(layout), 'Source Layout does not exist')
        local name = self.basename(dir, 'snapshot')
        local path = dir .. '/' .. name .. '.xml'
        -- No /overwrite or /noconfirm, and no drive/destination changes.
        g.cmd(string.format('Export Layout %d "%s" /path="%s"', layout, name, dir))
        for _ = 1, 20 do
            if self.exists(path) then break end
            if type(g.sleep) ~= 'function' then break end
            g.sleep(0.1)
        end
        local text = self.read(path)
        core.read(text) -- Never accept an unrecognised export format.
        return text, path
    end
    function self.probe(address)
        check(type(address) == 'string' and (address:match('^Layout %d+$') or address:match('^Fixture %d+$')), 'Unsupported probe address')
        local h = obj.handle(address)
        check(h and h ~= 0, 'Probe object missing')
        local prop = g.show.property
        self.log('PROBE (read only): ' .. address)
        self.log('Lua runtime: ' .. tostring(_VERSION))
        for _, name in ipairs({'build_date', 'build_time', 'git_version'}) do
            if type(g[name]) == 'function' then
                local ok, value = pcall(g[name])
                self.log('gma.' .. name .. ': ' .. (ok and tostring(value) or '<read error>'))
            end
        end
        local visited, budget = {}, 200
        local function visit(node, label, depth)
            if not node or node == 0 or visited[node] or budget == 0 then return end
            visited[node], budget = true, budget - 1
            self.log(label)
            if prop and prop.amount and prop.name and prop.get then
                local ok, n = pcall(prop.amount, node)
                if ok and type(n) == 'number' then
                    for i = 0, math.min(n, 256) - 1 do
                        local nk, name = pcall(prop.name, node, i)
                        if nk and name then
                            local vk, value = pcall(prop.get, node, name)
                            self.log('  [' .. i .. '] ' .. name .. '=' .. (vk and tostring(value) or '<read error>'))
                        end
                    end
                end
            else self.log('  Property enumeration unavailable') end
            if depth < 2 and obj.amount and obj.child then
                local ok, n = pcall(obj.amount, node)
                if ok and type(n) == 'number' then
                    self.log('  Child count: ' .. n)
                    for i = 0, math.min(n, 200) - 1 do
                        local ck, child = pcall(obj.child, node, i)
                        if ck then visit(child, label .. '/child[' .. i .. ']', depth + 1) end
                    end
                end
            end
        end
        visit(h, address, 0)
        self.log('Probe bounded to depth 2 / 200 objects / 256 properties each. Absence is not proof of API impossibility.')
    end
    local function group_bytes(text)
        local m = core.read(text)
        return text:sub(m.group.start, m.group.finish)
    end
    function self.create(source_layout, target_layout, dir, plan, output_path)
        source_layout, target_layout = core.id(source_layout), core.id(target_layout)
        dir = self.directory(dir)
        check(source_layout ~= target_layout and not handle(target_layout), 'Destination must be an EMPTY Layout slot')
        check(self.read(output_path) == plan.output, 'Output file changed after preview')
        local token = 'CREATE ' .. target_layout
        local reply = self.ask('New Layout ' .. target_layout .. ', ' .. #plan.changes .. ' pixels. Review TXT first. Type ' .. token, '')
        if reply ~= token then self.log('Cancelled: no import executed'); return false end
        -- User may have changed the show while the dialog was open.
        local fresh = self.export(source_layout, dir)
        check(group_bytes(fresh) == group_bytes(plan.source_text), 'Source Layout changed since preview; run again')
        check(self.read(output_path) == plan.output, 'Output file changed after confirmation')
        check(not handle(target_layout), 'Destination occupied since preview; import blocked')
        -- The only show-writing command. Keep MA2's own confirmation enabled.
        local name = check(output_path:match('/(la_result_[%w_]+)%.xml$'), 'Unexpected output filename')
        check(output_path == dir .. '/' .. name .. '.xml', 'Output directory mismatch')
        g.cmd(string.format('Import "%s" At Layout %d /path="%s"', name, target_layout, dir))
        for _ = 1, 20 do
            if handle(target_layout) then break end
            if type(g.sleep) ~= 'function' then break end
            g.sleep(0.1)
        end
        check(handle(target_layout), 'Import not verified; inspect MA2 feedback. No automatic retry/delete performed')
        local actual = core.read(self.export(target_layout, dir))
        for _, change in ipairs(plan.changes) do
            local entries = actual.by_fixture[change.fix_id]
            local e = entries and entries[change.index]
            check(e and math.abs(e.x - change.x) <= 0.0011 and math.abs(e.y - change.y) <= 0.0011,
                'Layout exists, but coordinate verification failed. Inspect it manually; no cleanup performed')
        end
        self.log('Created Layout ' .. target_layout .. '; target coordinates verified by re-export (tolerance 0.0011).')
        return true
    end
    return self
end
return M

end
factories["layout_assistant.ui"] = function()
local core = require('layout_assistant.core')
local ma2 = require('layout_assistant.ma2')
local M = {}
local function list(text, convert)
    local out = {}
    if text:match('^%s*$') or text:match('^%s*,') or text:match(',%s*$') or text:match(',%s*,') then error('Expected comma-separated values', 0) end
    for token in text:gmatch('[^,]+') do
        token = token:match('^%s*(.-)%s*$')
        out[#out + 1] = convert(token)
    end
    return out
end
function M.run(g, filesystem)
    local a = ma2.new(g, filesystem)
    local mode = a.ask('Layout Assistant: probe / preview / create', 'probe')
    if mode == '' then return end
    if mode ~= 'probe' and mode ~= 'preview' and mode ~= 'create' then error('Unknown mode', 0) end
    local layout = core.id(a.ask('Existing Layout number', ''))
    if mode == 'probe' then
        a.probe('Layout ' .. layout)
        local fid = a.ask('Optional Fixture ID for read-only probe (empty = skip)', '')
        if fid ~= '' then a.probe('Fixture ' .. core.id(fid)) end
        return
    end
    local dir = a.directory(a.ask('Absolute existing importexport directory (see manual)', ''))
    local text, snapshot = a.export(layout, dir)
    local model = core.read(text)
    a.log('Snapshot kept: ' .. snapshot)
    local fid = core.id(a.ask('Template Fixture ID', ''))
    local available = table.concat(core.indices(model, fid), ',')
    a.log('Template RAW XML indices: ' .. available .. '. These are not guaranteed to equal displayed .n numbers.')
    local source = {fix_id = fid,
        indices = list(a.ask('RAW XML indices to copy, in order; root = omitted sub_index', available), core.index),
        angle = core.number(a.ask('Template current Layout angle, degrees (CCW)', '0'), 'source angle')}
    local target_ids = list(a.ask('Target Fixture IDs, comma separated', ''), core.id)
    local targets = {}
    for _, id in ipairs(target_ids) do
        a.log('Target ' .. id .. ' RAW indices: ' .. table.concat(core.indices(model, id), ','))
        local target = {fix_id = id,
            indices = list(a.ask('Fixture ' .. id .. ': mapped RAW indices in template order', table.concat(source.indices, ',')), core.index),
            angle = core.number(a.ask('Fixture ' .. id .. ': absolute Layout angle (left/right may use opposite signs)', tostring(source.angle)), 'target angle'),
            mirror = a.ask('Fixture ' .. id .. ': none / flip_x / flip_y (LOCAL coordinates)', 'none')}
        local anchor = a.ask('Fixture ' .. id .. ': anchor x,y or centroid', 'centroid')
        if anchor ~= 'centroid' then
            local xy = list(anchor, function(n) return core.number(n, 'anchor') end)
            if #xy ~= 2 then error('Anchor needs x,y', 0) end
            target.x, target.y = xy[1], xy[2]
        end
        targets[#targets + 1] = target
    end
    local plan = core.plan(model, {jobs = {{source = source, targets = targets}}})
    local report = core.report(plan)
    for line in report:gmatch('[^\n]+') do a.log(line) end
    local name = a.basename(dir, 'result')
    local output_path = dir .. '/' .. name .. '.xml'
    a.write_new(output_path, plan.output)
    a.write_new(dir .. '/' .. name .. '.txt', report)
    a.log('Review XML/TXT: ' .. dir .. '/' .. name .. '.*')
    if mode == 'create' then
        local destination = core.id(a.ask('NEW EMPTY Layout number (existing slots are refused)', ''))
        a.create(layout, destination, dir, plan, output_path)
    else a.log('Preview finished: no show objects changed. Run create to generate and confirm a fresh plan.') end
end
return M

end
local function main()
    local ok, err = pcall(require("layout_assistant.ui").run, gma)
    if not ok then gma.feedback("Layout Assistant stopped: " .. tostring(err)) end
end
return main
